INSERT INTO public.materiales (seccion, nombre, uso, formato, detalle, marca, imagen_url, orden, publicado) VALUES
('sustratos','Turba natural (PM · Peat Moss)','Resiembra, siembra y trasplante de praderas; enmienda para plantas acidófilas (rododendros, azaleas).','70 L · 225 L · 4.000 L · 5.000 L','Turba negra ácida pH 3,5-4,5, descomposición H4-H6. Disponible en estructura fina, media (0-20 mm) y gruesa según necesidad de aireación y drenaje. Producto profesional.','Suliflor','/__l5e/assets-v1/9139e63a-a378-4439-9884-ba178da44778/suliflor-PM-SuliflorESP.png',1,true),
('sustratos','Turba de acidez reducida (SF-0)','Preparación de sustratos propios y mejora de suelos; apta para cultivo ecológico.','70 L · 225 L · 4.000 L · 5.000 L','Turba encalada con caliza y dolomita en polvo: pH 5,5-6,5 (bajo pedido de 4,5 a 7,0) y aporte de calcio y magnesio. Sin fertilizante añadido, el cultivador abona a su criterio.','Suliflor','/__l5e/assets-v1/046bd761-aaba-4367-b373-93a8f81aa0d6/suliflor-SF0-SuliflorESP.png',2,true),
('sustratos','Sustrato para semillero (SF-1)','Semilleros, planteles, camas de cultivo y hortícolas.','70 L · 225 L · 4.000 L · 5.000 L','Estructura fina con nivel bajo de fertilizante N-P2O5-K2O y microelementos, pH 5,5-6,5. Incluye agente humectante FIBA-ZORB para una humectación y rehumectación rápidas.','Suliflor','/__l5e/assets-v1/60bb45da-79eb-4546-8420-b1645506b94e/suliflor-SF1-SuliflorESP.png',3,true),
('sustratos','Sustrato universal (SF-2)','Uso general: hortícolas, planta de maceta, flor, follaje, colgantes y bulbos.','70 L · 225 L · 4.000 L · 5.000 L','Turba encalada pH 5,5-6,5 (bajo pedido 4,5-7,0) con fertilizante N-P2O5-K2O y microelementos, más agente humectante FIBA-ZORB para un drenaje y reparto de agua uniformes. Producto profesional.','Suliflor','/__l5e/assets-v1/15e7c2fa-c307-403e-999e-abf37b3acb90/suliflor-SF2-SuliflorESP.png',4,true),
('sustratos','Sustrato universal hobby (SF-2 Hobby)','Plantas de interior y exterior en maceta, jardinería doméstica.','45 L · 70 L · 150 L · 225 L','Turba de usos múltiples rica en nutrientes, con caliza molida y agente humectante. Alta retención de humedad y buen drenaje; se recomienda abonar de nuevo a las 4 semanas.','Suliflor','/__l5e/assets-v1/e0dbfb3b-4755-4fc9-9d00-93390ac7ccfb/traditional-universal.jpg',5,true),
('sustratos','Sustrato para rododendros y acidófilas','Rododendros, azaleas, camelias, brezos y demás plantas de suelo ácido.','45 L · 70 L · 250 L','Mezcla lista para usar de pH 3,5-4,5, enriquecida con fertilizante y agente humectante FIBA-ZORB. Turba esponjosa que asegura aireación perfecta con buena reserva de agua.','Suliflor','/__l5e/assets-v1/d2494641-3128-4a27-a0bc-bb4118dfe3c9/rododendrams.jpg',6,true);